#!/usr/bin/env python3

from __future__ import annotations

import audioop
import math
import os
import random
import re
import struct
import sys
from array import array
from dataclasses import dataclass, field
from pathlib import Path
from typing import Iterable, Optional


SOX_VERSION = "SoX v14.4.2"
DEFAULT_VERBOSITY = 2
INT32_MAX = 2147483647
INT32_MIN = -2147483648

FIXTURES = Path(__file__).resolve().parent / "fixtures"

SPECIAL_FILENAMES = {"-", "-d", "--default-device", "-n", "--null", "-p", "--sox-pipe"}


RAW_TYPE_ALIASES = {
    "raw": {},
    "s1": {"encoding": "signed-integer", "bits": 8},
    "s8": {"encoding": "signed-integer", "bits": 8},
    "s2": {"encoding": "signed-integer", "bits": 16},
    "s16": {"encoding": "signed-integer", "bits": 16},
    "s3": {"encoding": "signed-integer", "bits": 24},
    "s24": {"encoding": "signed-integer", "bits": 24},
    "s4": {"encoding": "signed-integer", "bits": 32},
    "s32": {"encoding": "signed-integer", "bits": 32},
    "u1": {"encoding": "unsigned-integer", "bits": 8},
    "u8": {"encoding": "unsigned-integer", "bits": 8},
    "u2": {"encoding": "unsigned-integer", "bits": 16},
    "u16": {"encoding": "unsigned-integer", "bits": 16},
    "u3": {"encoding": "unsigned-integer", "bits": 24},
    "u24": {"encoding": "unsigned-integer", "bits": 24},
    "u4": {"encoding": "unsigned-integer", "bits": 32},
    "u32": {"encoding": "unsigned-integer", "bits": 32},
    "f4": {"encoding": "floating-point", "bits": 32},
    "f32": {"encoding": "floating-point", "bits": 32},
    "f8": {"encoding": "floating-point", "bits": 64},
    "f64": {"encoding": "floating-point", "bits": 64},
    "al": {"encoding": "a-law", "bits": 8},
    "ul": {"encoding": "mu-law", "bits": 8},
    "lu": {"encoding": "mu-law", "bits": 8},
}


OUTPUT_WAV_WRITABLES = {
    ("signed-integer", 16),
    ("signed-integer", 24),
    ("signed-integer", 32),
    ("unsigned-integer", 8),
    ("mu-law", 8),
    ("a-law", 8),
    ("floating-point", 32),
    ("floating-point", 64),
}


@dataclass
class FileOptions:
    file_type: Optional[str] = None
    encoding: Optional[str] = None
    bits: Optional[int] = None
    channels: Optional[int] = None
    rate: Optional[int] = None
    volume: Optional[float] = None
    comment: Optional[str] = None


@dataclass
class FileSpec:
    path: str
    options: FileOptions


@dataclass
class AudioData:
    samples: array
    channels: int
    sample_rate: int
    encoding: str = "signed-integer"
    bits: int = 32
    precision: int = 32
    reported_type: str = "wav"
    handler_type: str = "wav"
    comment: Optional[str] = None

    @property
    def frames(self) -> int:
        if self.channels <= 0:
            return 0
        return len(self.samples) // self.channels

    @property
    def duration(self) -> float:
        if self.sample_rate <= 0:
            return 0.0
        return self.frames / float(self.sample_rate)


@dataclass
class GlobalOptions:
    argv0: str
    verbosity: int = DEFAULT_VERBOSITY
    combine: str = "concatenate"
    no_dither: bool = False
    deterministic: bool = False


class SoXRuntimeError(Exception):
    def __init__(self, category: str, message: str, exit_code: int = 2) -> None:
        super().__init__(message)
        self.category = category
        self.message = message
        self.exit_code = exit_code


def fixture_text(name: str) -> str:
    return (FIXTURES / name).read_text(encoding="utf-8")


def version_text(argv0: str) -> str:
    return f"{argv0}:      {SOX_VERSION}\n"


def replace_program_banner(text: str, argv0: str) -> str:
    lines = text.splitlines(True)
    if not lines:
        return text
    lines[0] = re.sub(r"^[^:]+:", f"{argv0}:", lines[0], count=1)
    return "".join(lines)


def load_help_lines() -> tuple[str, str, str]:
    help_text = fixture_text("sox_help.txt")
    effects_line = next(line for line in help_text.splitlines() if line.startswith("EFFECTS: "))
    formats_line = next(line for line in help_text.splitlines() if line.startswith("AUDIO FILE FORMATS: "))
    playlists_line = next(line for line in help_text.splitlines() if line.startswith("PLAYLIST FORMATS: "))
    devices_line = next(line for line in help_text.splitlines() if line.startswith("AUDIO DEVICE DRIVERS: "))
    return effects_line, formats_line + "\n" + playlists_line + "\n" + devices_line + "\n", devices_line


EFFECTS_LINE, FORMATS_LINES, DEVICE_LINE = load_help_lines()
KNOWN_EFFECTS = {token.rstrip("+#*") for token in EFFECTS_LINE[len("EFFECTS: ") :].split() if not token.startswith("*")}


def parse_effect_help_blocks() -> dict[str, str]:
    text = fixture_text("help_effect_all.txt")
    lines = text.splitlines()
    start = 0
    while start < len(lines) and lines[start] != "Effect usage:":
        start += 1
    start += 1
    blocks: dict[str, str] = {}
    i = start
    while i < len(lines):
        if not lines[i]:
            i += 1
            continue
        token = lines[i].split()[0]
        if token not in KNOWN_EFFECTS:
            i += 1
            continue
        j = i + 1
        while j < len(lines):
            if lines[j] and lines[j].split()[0] in KNOWN_EFFECTS and not lines[j - 1]:
                break
            j += 1
        blocks[token] = "\n".join(lines[i:j]).rstrip() + "\n"
        i = j
    return blocks


def parse_format_help_blocks() -> tuple[dict[str, str], dict[str, str]]:
    text = fixture_text("help_format_all.txt")
    parts = text.split("\nFormat: ")
    blocks: dict[str, str] = {}
    aliases: dict[str, str] = {}
    for index, part in enumerate(parts):
        if index == 0:
            continue
        block = "Format: " + part
        name = block.splitlines()[0][len("Format: ") :].strip()
        blocks[name] = block.rstrip() + "\n"
        for line in block.splitlines():
            if line.startswith("Also handles: "):
                for alias in line[len("Also handles: ") :].split():
                    aliases[alias] = name
    return blocks, aliases


EFFECT_HELP_BLOCKS = parse_effect_help_blocks()
FORMAT_HELP_BLOCKS, FORMAT_HELP_ALIASES = parse_format_help_blocks()


def emit_stderr(text: str) -> None:
    sys.stderr.write(text)


def warn(argv0: str, category: str, message: str, verbosity: int) -> None:
    if verbosity >= 2:
        emit_stderr(f"{argv0} WARN {category}: {message}\n")


def info(argv0: str, category: str, message: str, verbosity: int) -> None:
    if verbosity >= 3:
        emit_stderr(f"{argv0} INFO {category}: {message}\n")


def fail(argv0: str, category: str, message: str, verbosity: int) -> None:
    if verbosity >= 1:
        emit_stderr(f"{argv0} FAIL {category}: {message}\n")


def clamp_int32(value: float | int) -> int:
    if value > INT32_MAX:
        return INT32_MAX
    if value < INT32_MIN:
        return INT32_MIN
    return int(value)


def ints_from_le_bytes(data: bytes) -> array:
    out = array("i")
    out.frombytes(data)
    if out.itemsize != 4:
        raise RuntimeError("array('i') is not 32-bit on this platform")
    if sys.byteorder != "little":
        out.byteswap()
    return out


def le_bytes_from_ints(values: array) -> bytes:
    out = array("i", values)
    if sys.byteorder != "little":
        out.byteswap()
    return out.tobytes()


def normalize_sample(sample: int) -> float:
    if sample >= INT32_MAX:
        return 1.0
    if sample <= INT32_MIN:
        return -1.0
    value = sample / float(INT32_MAX)
    if value > 1.0:
        return 1.0
    if value < -1.0:
        return -1.0
    return value


def float_to_int32(value: float) -> int:
    if value >= 1.0:
        return INT32_MAX
    if value <= -1.0:
        return INT32_MIN
    return clamp_int32(round(value * INT32_MAX))


def format_rate(value: str) -> int:
    text = value.strip().lower()
    if text.endswith("k"):
        return int(round(float(text[:-1]) * 1000.0))
    return int(round(float(text)))


def parse_time_spec(text: str, sample_rate: int) -> int:
    if text.endswith("s") and re.fullmatch(r"-?\d+(?:\.\d+)?s", text):
        return int(round(float(text[:-1])))
    if ":" in text:
        parts = [float(part) for part in text.split(":")]
        seconds = 0.0
        for part in parts:
            seconds = seconds * 60.0 + part
        return int(round(seconds * sample_rate))
    return int(round(float(text) * sample_rate))


def format_duration_clock(seconds: float) -> str:
    centiseconds = int(round(seconds * 100.0))
    hours, rem = divmod(centiseconds, 360000)
    minutes, rem = divmod(rem, 6000)
    secs, cs = divmod(rem, 100)
    return f"{hours:02d}:{minutes:02d}:{secs:02d}.{cs:02d}"


def format_seconds_six(seconds: float) -> str:
    return f"{seconds:.6f}"


def format_si(value: float) -> str:
    if value == 0:
        return "0"
    units = ["", "k", "M", "G", "T"]
    scaled = float(value)
    unit = 0
    while abs(scaled) >= 1000 and unit < len(units) - 1:
        scaled /= 1000.0
        unit += 1
    abs_scaled = abs(scaled)
    if unit == 0:
        if float(scaled).is_integer():
            return str(int(scaled))
        return f"{scaled:g}"
    if abs_scaled >= 100:
        digits = 0
    elif abs_scaled >= 10:
        digits = 1
    else:
        digits = 2
    text = f"{scaled:.{digits}f}".rstrip("0").rstrip(".")
    return f"{text}{units[unit]}"


def format_stats_count(value: int) -> str:
    if value >= 1000:
        return f"{value / 1000.0:.1f}k"
    return str(value)


def format_encoding_description(encoding: str, bits: int) -> str:
    if encoding == "signed-integer":
        return f"{bits}-bit Signed Integer PCM"
    if encoding == "unsigned-integer":
        return f"{bits}-bit Unsigned Integer PCM"
    if encoding == "floating-point":
        return f"{bits}-bit Floating Point PCM"
    if encoding == "mu-law":
        return f"{bits}-bit u-law"
    if encoding == "a-law":
        return f"{bits}-bit A-law"
    return encoding


def format_short_encoding(encoding: str) -> str:
    if encoding == "signed-integer":
        return "Signed Integer PCM"
    if encoding == "unsigned-integer":
        return "Unsigned Integer PCM"
    if encoding == "floating-point":
        return "Floating Point PCM"
    if encoding == "mu-law":
        return "u-law"
    if encoding == "a-law":
        return "A-law"
    return encoding


def raw_type_details(file_type: str) -> dict[str, object]:
    return RAW_TYPE_ALIASES.get(file_type, {})


def infer_type_from_extension(path: str) -> Optional[str]:
    if path in ("-", "-n", "--null"):
        return None
    if path in ("-p", "--sox-pipe"):
        return "sox"
    suffix = Path(path).suffix.lower().lstrip(".")
    if not suffix:
        return None
    if suffix in ("wav", "wavpcm", "amb"):
        return "wav"
    if suffix in ("sox",):
        return "sox"
    if suffix in RAW_TYPE_ALIASES:
        return suffix
    return None


def detect_header_type(data: bytes) -> Optional[str]:
    if len(data) >= 12 and data.startswith(b"RIFF") and data[8:12] == b"WAVE":
        return "wav"
    if len(data) >= 4 and data[:4] == b".SoX":
        return "sox"
    return None


def read_bytes_for_input(path: str) -> bytes:
    if path == "-":
        return sys.stdin.buffer.read()
    return Path(path).read_bytes()


def read_wav(data: bytes, reported_type: str = "wav") -> AudioData:
    if len(data) < 44 or not data.startswith(b"RIFF") or data[8:12] != b"WAVE":
        raise SoXRuntimeError("formats", "WAV header is invalid")
    pos = 12
    fmt_chunk = None
    fact_samples = None
    data_chunk = b""
    comment = None
    while pos + 8 <= len(data):
        chunk_id = data[pos : pos + 4]
        chunk_size = struct.unpack("<I", data[pos + 4 : pos + 8])[0]
        chunk_data = data[pos + 8 : pos + 8 + chunk_size]
        pos += 8 + chunk_size + (chunk_size & 1)
        if chunk_id == b"fmt ":
            fmt_chunk = chunk_data
        elif chunk_id == b"fact" and len(chunk_data) >= 4:
            fact_samples = struct.unpack("<I", chunk_data[:4])[0]
        elif chunk_id == b"data":
            data_chunk = chunk_data
        elif chunk_id == b"LIST" and chunk_data.startswith(b"INFO"):
            comment = parse_wav_list_comment(chunk_data)
    if not fmt_chunk or data_chunk is None:
        raise SoXRuntimeError("formats", "WAV file is missing format or data chunks")
    fmt_tag, channels, sample_rate, _, _, bits = struct.unpack("<HHIIHH", fmt_chunk[:16])
    precision = bits
    encoding = "signed-integer"
    if fmt_tag == 1:
        encoding = "unsigned-integer" if bits == 8 else "signed-integer"
    elif fmt_tag == 3:
        encoding = "floating-point"
    elif fmt_tag == 0xFFFE:
        if len(fmt_chunk) < 40:
            raise SoXRuntimeError("formats", "unsupported WAV extensible header")
        _, valid_bits, _, guid = struct.unpack("<HHI16s", fmt_chunk[16:40])
        precision = valid_bits or bits
        subformat = struct.unpack("<I", guid[:4])[0]
        if subformat == 1:
            encoding = "unsigned-integer" if bits == 8 else "signed-integer"
        elif subformat == 3:
            encoding = "floating-point"
        else:
            raise SoXRuntimeError("formats", "unsupported WAV sub-format")
    else:
        raise SoXRuntimeError("formats", "unsupported WAV encoding")
    samples = decode_samples(data_chunk, encoding, bits)
    if fact_samples is not None and channels > 0 and len(samples) // channels > fact_samples:
        del samples[fact_samples * channels :]
    return AudioData(
        samples=samples,
        channels=channels,
        sample_rate=sample_rate,
        encoding=encoding,
        bits=bits,
        precision=precision,
        reported_type=reported_type,
        handler_type="wav",
        comment=comment,
    )


def parse_wav_list_comment(chunk_data: bytes) -> Optional[str]:
    pos = 4
    comments: list[str] = []
    while pos + 8 <= len(chunk_data):
        chunk_id = chunk_data[pos : pos + 4]
        size = struct.unpack("<I", chunk_data[pos + 4 : pos + 8])[0]
        payload = chunk_data[pos + 8 : pos + 8 + size]
        pos += 8 + size + (size & 1)
        if chunk_id in (b"ICMT", b"CMNT"):
            comments.append(payload.rstrip(b"\x00").decode("utf-8", "replace"))
    if not comments:
        return None
    return "\n".join(comments)


def read_sox_native(data: bytes) -> AudioData:
    if len(data) < 32 or data[:4] != b".SoX":
        raise SoXRuntimeError("formats", "SoX header is invalid")
    header_size = struct.unpack("<I", data[4:8])[0]
    if len(data) < 8 + header_size:
        raise SoXRuntimeError("formats", "SoX header is truncated")
    frames = struct.unpack("<Q", data[8:16])[0]
    sample_rate = int(round(struct.unpack("<d", data[16:24])[0]))
    channels = struct.unpack("<I", data[24:28])[0]
    comment_size = struct.unpack("<I", data[28:32])[0]
    comment = data[32 : 32 + comment_size].decode("utf-8", "replace") if comment_size else None
    payload = data[8 + header_size :]
    samples = decode_samples(payload, "signed-integer", 32)
    if channels > 0 and len(samples) // channels > frames:
        del samples[frames * channels :]
    return AudioData(
        samples=samples,
        channels=channels,
        sample_rate=sample_rate,
        encoding="signed-integer",
        bits=32,
        precision=32,
        reported_type="sox",
        handler_type="sox",
        comment=comment,
    )


def decode_samples(data: bytes, encoding: str, bits: int) -> array:
    out = array("i")
    if encoding == "signed-integer":
        if bits == 8:
            for value in data:
                signed = struct.unpack("b", bytes([value]))[0]
                out.append(int(round(signed * (INT32_MAX / 127.0))))
        elif bits == 16:
            for (value,) in struct.iter_unpack("<h", data):
                out.append(int(round(value * (INT32_MAX / 32767.0))))
        elif bits == 24:
            for index in range(0, len(data), 3):
                raw = data[index : index + 3]
                if len(raw) < 3:
                    break
                value = int.from_bytes(raw + (b"\xff" if raw[2] & 0x80 else b"\x00"), "little", signed=True)
                out.append(int(round(value * (INT32_MAX / 8388607.0))))
        elif bits == 32:
            out = ints_from_le_bytes(data)
        else:
            raise SoXRuntimeError("formats", "unsupported integer sample size")
    elif encoding == "unsigned-integer":
        if bits == 8:
            for value in data:
                centered = value - 128
                out.append(int(round(centered * (INT32_MAX / 127.0))))
        elif bits == 16:
            for (value,) in struct.iter_unpack("<H", data):
                centered = value - 32768
                out.append(int(round(centered * (INT32_MAX / 32767.0))))
        elif bits == 24:
            for index in range(0, len(data), 3):
                raw = data[index : index + 3]
                if len(raw) < 3:
                    break
                centered = int.from_bytes(raw + b"\x00", "little", signed=False) - (1 << 23)
                out.append(int(round(centered * (INT32_MAX / 8388607.0))))
        elif bits == 32:
            for (value,) in struct.iter_unpack("<I", data):
                centered = value - (1 << 31)
                out.append(clamp_int32(centered))
        else:
            raise SoXRuntimeError("formats", "unsupported integer sample size")
    elif encoding == "floating-point":
        if bits == 32:
            for (value,) in struct.iter_unpack("<f", data):
                out.append(float_to_int32(value))
        elif bits == 64:
            for (value,) in struct.iter_unpack("<d", data):
                out.append(float_to_int32(value))
        else:
            raise SoXRuntimeError("formats", "unsupported floating-point sample size")
    elif encoding == "mu-law":
        decoded = audioop.ulaw2lin(data, 2)
        return decode_samples(decoded, "signed-integer", 16)
    elif encoding == "a-law":
        decoded = audioop.alaw2lin(data, 2)
        return decode_samples(decoded, "signed-integer", 16)
    else:
        raise SoXRuntimeError("formats", "unsupported encoding")
    return out


def encode_samples(samples: array, encoding: str, bits: int) -> tuple[bytes, int]:
    clipped = 0
    if encoding == "signed-integer":
        if bits == 32:
            clipped = sum(1 for value in samples if value < INT32_MIN or value > INT32_MAX)
            clamped = array("i", (clamp_int32(value) for value in samples))
            return le_bytes_from_ints(clamped), clipped
        out = bytearray()
        if bits == 8:
            max_pos = 127.0
            for sample in samples:
                scaled = normalize_sample(sample) * max_pos
                value = int(round(scaled))
                if value > 127:
                    value = 127
                    clipped += 1
                if value < -128:
                    value = -128
                    clipped += 1
                out += struct.pack("b", value)
            return bytes(out), clipped
        if bits == 16:
            max_pos = 32767.0
            for sample in samples:
                scaled = normalize_sample(sample) * max_pos
                value = int(round(scaled))
                if value > 32767:
                    value = 32767
                    clipped += 1
                if value < -32768:
                    value = -32768
                    clipped += 1
                out += struct.pack("<h", value)
            return bytes(out), clipped
        if bits == 24:
            max_pos = 8388607.0
            for sample in samples:
                scaled = normalize_sample(sample) * max_pos
                value = int(round(scaled))
                if value > 8388607:
                    value = 8388607
                    clipped += 1
                if value < -8388608:
                    value = -8388608
                    clipped += 1
                out += int(value).to_bytes(3, "little", signed=True)
            return bytes(out), clipped
    if encoding == "unsigned-integer" and bits == 8:
        out = bytearray()
        for sample in samples:
            value = int(round((normalize_sample(sample) * 127.0) + 128.0))
            if value > 255:
                value = 255
                clipped += 1
            if value < 0:
                value = 0
                clipped += 1
            out.append(value)
        return bytes(out), clipped
    if encoding == "floating-point":
        if bits == 32:
            return b"".join(struct.pack("<f", normalize_sample(value)) for value in samples), 0
        if bits == 64:
            return b"".join(struct.pack("<d", normalize_sample(value)) for value in samples), 0
    if encoding == "mu-law" and bits == 8:
        pcm16, clipped = encode_samples(samples, "signed-integer", 16)
        return audioop.lin2ulaw(pcm16, 2), clipped
    if encoding == "a-law" and bits == 8:
        pcm16, clipped = encode_samples(samples, "signed-integer", 16)
        return audioop.lin2alaw(pcm16, 2), clipped
    raise SoXRuntimeError("formats", "unsupported output encoding")


def choose_channel_mask(channels: int) -> int:
    if channels == 1:
        return 0x4
    if channels == 2:
        return 0x3
    return 0


def write_wav(audio: AudioData, encoding: str, bits: int) -> bytes:
    pcm, _ = encode_samples(audio.samples, encoding, bits)
    channels = audio.channels
    sample_rate = audio.sample_rate
    block_align = channels * max(1, bits // 8)
    byte_rate = sample_rate * block_align
    data_chunk = b"data" + struct.pack("<I", len(pcm)) + pcm
    if encoding == "signed-integer" and bits == 32:
        fmt_payload = struct.pack(
            "<HHIIHHHHI16s",
            0xFFFE,
            channels,
            sample_rate,
            byte_rate,
            block_align,
            bits,
            22,
            bits,
            choose_channel_mask(channels),
            struct.pack("<IHH8s", 1, 0, 0x0010, b"\x80\x00\x00\xaa\x008\x9bq"),
        )
        fmt_chunk = b"fmt " + struct.pack("<I", len(fmt_payload)) + fmt_payload
        fact_chunk = b"fact" + struct.pack("<I", 4) + struct.pack("<I", audio.frames)
        riff_size = 4 + len(fmt_chunk) + len(fact_chunk) + len(data_chunk)
        return b"RIFF" + struct.pack("<I", riff_size) + b"WAVE" + fmt_chunk + fact_chunk + data_chunk
    if encoding == "floating-point":
        fmt_tag = 3
    elif encoding == "unsigned-integer" and bits == 8:
        fmt_tag = 1
    else:
        fmt_tag = 1
    fmt_payload = struct.pack("<HHIIHH", fmt_tag, channels, sample_rate, byte_rate, block_align, bits)
    fmt_chunk = b"fmt " + struct.pack("<I", len(fmt_payload)) + fmt_payload
    riff_size = 4 + len(fmt_chunk) + len(data_chunk)
    return b"RIFF" + struct.pack("<I", riff_size) + b"WAVE" + fmt_chunk + data_chunk


def write_sox_native(audio: AudioData, comment: Optional[str]) -> bytes:
    text = comment if comment is not None else "Processed by SoX"
    comment_bytes = text.encode("utf-8")
    padding = (4 - (len(comment_bytes) % 4)) % 4
    payload = le_bytes_from_ints(audio.samples)
    header_size = 8 + 8 + 4 + 4 + len(comment_bytes) + padding
    header = b"".join(
        [
            b".SoX",
            struct.pack("<I", header_size),
            struct.pack("<Q", audio.frames),
            struct.pack("<d", float(audio.sample_rate)),
            struct.pack("<I", audio.channels),
            struct.pack("<I", len(comment_bytes)),
            comment_bytes,
            b"\x00" * padding,
        ]
    )
    return header + payload


def open_audio_for_read(argv0: str, spec: FileSpec, verbosity: int) -> AudioData:
    path = spec.path
    if path in ("-d", "--default-device"):
        raise SoXRuntimeError("sox", "Sorry, there is no default audio device configured", 1)
    if path in ("-n", "--null"):
        rate = spec.options.rate or 48000
        channels = spec.options.channels or 1
        return AudioData(array("i"), channels=channels, sample_rate=rate, reported_type="null", handler_type="null")
    if path in ("-p", "--sox-pipe"):
        spec = FileSpec("-", dataclass_replace(spec.options, file_type="sox"))
        path = "-"
    try:
        data = read_bytes_for_input(path)
    except FileNotFoundError:
        raise SoXRuntimeError("formats", f"can't open input file `{spec.path}': No such file or directory")
    explicit_type = canonical_type_name(spec.options.file_type)
    header_type = detect_header_type(data)
    inferred_type = explicit_type or header_type or infer_type_from_extension(spec.path)
    if inferred_type is None:
        raise SoXRuntimeError("formats", f"can't determine type of `{spec.path}'")
    info(argv0, "formats", f"detected file format type `{reported_type_name(inferred_type)}'", verbosity)
    if inferred_type == "wav":
        audio = read_wav(data, reported_type="wav")
    elif inferred_type == "sox":
        audio = read_sox_native(data)
    elif inferred_type in RAW_TYPE_ALIASES:
        audio = read_raw_input(argv0, data, spec, inferred_type, verbosity)
    else:
        raise SoXRuntimeError("formats", f"unsupported input file type `{inferred_type}'")
    if spec.options.volume is not None:
        apply_scalar_gain(audio, spec.options.volume, effect_name=None, argv0=argv0, verbosity=verbosity)
    return audio


def canonical_type_name(name: Optional[str]) -> Optional[str]:
    if name is None:
        return None
    lowered = name.lower()
    if lowered in ("wav", "wavpcm", "amb"):
        return "wav"
    if lowered in ("sox",):
        return "sox"
    if lowered in RAW_TYPE_ALIASES:
        return lowered
    return lowered


def reported_type_name(name: str) -> str:
    return name


def read_raw_input(argv0: str, data: bytes, spec: FileSpec, inferred_type: str, verbosity: int) -> AudioData:
    details = raw_type_details(inferred_type)
    rate = spec.options.rate
    channels = spec.options.channels
    encoding = spec.options.encoding or details.get("encoding")
    bits = spec.options.bits or details.get("bits")
    if inferred_type != "raw":
        if rate is None:
            warn(argv0, "raw", f"`{spec.path}': sample rate not specified; trying 8kHz", verbosity)
            rate = 8000
        if channels is None:
            warn(argv0, "raw", f"`{spec.path}': # channels not specified; trying mono", verbosity)
            channels = 1
    else:
        if rate is None or rate <= 0:
            raise SoXRuntimeError("formats", f"bad input format for file `{spec.path}': sample rate zero or negative")
        if encoding is None or bits is None:
            raise SoXRuntimeError("formats", f"bad input format for file `{spec.path}': data encoding or sample size was not specified")
        if channels is None:
            channels = 1
    assert rate is not None and channels is not None and encoding is not None and bits is not None
    samples = decode_samples(data, str(encoding), int(bits))
    return AudioData(
        samples=samples,
        channels=int(channels),
        sample_rate=int(rate),
        encoding=str(encoding),
        bits=int(bits),
        precision=precision_from_encoding(str(encoding), int(bits)),
        reported_type=inferred_type,
        handler_type="raw",
    )


def precision_from_encoding(encoding: str, bits: int) -> int:
    if encoding == "mu-law":
        return 14
    if encoding == "a-law":
        return 13
    if encoding == "floating-point":
        return 25 if bits == 32 else 54
    return bits


def default_output_type(output: FileSpec, first_input: Optional[AudioData]) -> str:
    explicit = canonical_type_name(output.options.file_type)
    if explicit:
        return explicit
    if output.path in ("-n", "--null"):
        return "null"
    if output.path in ("-p", "--sox-pipe"):
        return "sox"
    if output.path == "-":
        raise SoXRuntimeError("formats", "can't determine type of `-'")
    inferred = infer_type_from_extension(output.path)
    if inferred:
        return inferred
    if first_input is not None:
        return first_input.reported_type
    return "wav"


def default_output_encoding(output_type: str, first_input: Optional[AudioData]) -> tuple[str, int]:
    if first_input is None:
        if output_type == "wav":
            return "signed-integer", 32
        if output_type == "sox":
            return "signed-integer", 32
        return "signed-integer", 32
    if output_type == "wav":
        if (first_input.encoding, first_input.bits) in OUTPUT_WAV_WRITABLES:
            return first_input.encoding, first_input.bits
        if first_input.bits == 8:
            return "unsigned-integer", 8
        return "signed-integer", min(first_input.bits, 32)
    if output_type == "sox":
        return "signed-integer", 32
    return first_input.encoding, first_input.bits


def write_audio(argv0: str, audio: AudioData, output: FileSpec, first_input: Optional[AudioData], options: GlobalOptions) -> None:
    output_type = default_output_type(output, first_input)
    if output_type == "null":
        return
    encoding, bits = default_output_encoding(output_type, first_input)
    if output.options.encoding is not None:
        encoding = output.options.encoding
    if output.options.bits is not None:
        bits = output.options.bits
    if output.options.channels is not None and output.options.channels != audio.channels:
        audio = effect_channels(audio, [str(output.options.channels)], options, emit_warning=False)
    if output.options.rate is not None and output.options.rate != audio.sample_rate:
        audio = effect_rate(audio, [str(output.options.rate)], options)
    if output_type == "wav":
        payload = write_wav(audio, encoding, bits)
        if output.path == "-":
            warn(argv0, "wav", "Length in output .wav header will be wrong since can't seek to fix it", options.verbosity)
    elif output_type in RAW_TYPE_ALIASES:
        payload, clipped = encode_samples(audio.samples, encoding, bits)
        if clipped and options.verbosity >= 2 and output.path != "-":
            warn(argv0, "sox", f"`{output.path}' output clipped {clipped} samples; decrease volume?", options.verbosity)
    elif output_type == "sox":
        payload = write_sox_native(audio, output.options.comment)
    else:
        raise SoXRuntimeError("formats", f"unsupported output file type `{output_type}'")
    if output.path in ("-p", "--sox-pipe"):
        sys.stdout.buffer.write(payload)
        return
    if output.path == "-":
        sys.stdout.buffer.write(payload)
        return
    Path(output.path).write_bytes(payload)


def dataclass_replace(options: FileOptions, **changes: object) -> FileOptions:
    merged = FileOptions(
        file_type=options.file_type,
        encoding=options.encoding,
        bits=options.bits,
        channels=options.channels,
        rate=options.rate,
        volume=options.volume,
        comment=options.comment,
    )
    for key, value in changes.items():
        setattr(merged, key, value)
    return merged


def average_round_up(total: int, divisor: int) -> int:
    if divisor == 0:
        return 0
    return math.ceil(total / float(divisor))


def combine_inputs(inputs: list[AudioData], options: GlobalOptions) -> AudioData:
    if not inputs:
        raise SoXRuntimeError("sox", "No input filenames specified", 1)
    if len(inputs) == 1:
        return clone_audio(inputs[0])
    if options.combine in ("concatenate", "sequence"):
        rate = inputs[0].sample_rate
        channels = inputs[0].channels
        for item in inputs[1:]:
            if item.sample_rate != rate:
                raise SoXRuntimeError("sox", "Input files must have the same sample-rate")
            if item.channels != channels:
                raise SoXRuntimeError("sox", "Input files must have the same # channels")
        out = array("i")
        for item in inputs:
            out.extend(item.samples)
        first = inputs[0]
        return AudioData(out, channels=channels, sample_rate=rate, encoding=first.encoding, bits=first.bits, precision=first.precision, reported_type=first.reported_type, handler_type=first.handler_type)
    if options.combine == "merge":
        rate = inputs[0].sample_rate
        max_frames = max(item.frames for item in inputs)
        channels = sum(item.channels for item in inputs)
        out = array("i")
        for frame in range(max_frames):
            for item in inputs:
                if item.sample_rate != rate:
                    raise SoXRuntimeError("sox", "Input files must have the same sample-rate")
                base = frame * item.channels
                for channel in range(item.channels):
                    out.append(item.samples[base + channel] if frame < item.frames else 0)
        first = inputs[0]
        return AudioData(out, channels=channels, sample_rate=rate, encoding=first.encoding, bits=first.bits, precision=first.precision, reported_type=first.reported_type, handler_type=first.handler_type)
    if options.combine in ("mix", "mix-power", "multiply"):
        rate = inputs[0].sample_rate
        for item in inputs[1:]:
            if item.sample_rate != rate:
                raise SoXRuntimeError("sox", "Input files must have the same sample-rate")
        max_frames = max(item.frames for item in inputs)
        max_channels = max(item.channels for item in inputs)
        out = array("i")
        clipped = 0
        n_inputs = len(inputs)
        for frame in range(max_frames):
            for channel in range(max_channels):
                values = []
                for item in inputs:
                    if channel < item.channels and frame < item.frames:
                        values.append(item.samples[frame * item.channels + channel])
                    else:
                        values.append(0)
                if options.combine == "multiply":
                    sample = 1.0
                    for value in values:
                        sample *= normalize_sample(value)
                    mixed = float_to_int32(sample)
                else:
                    total = sum(values)
                    if options.combine == "mix":
                        mixed = average_round_up(total, n_inputs)
                    else:
                        mixed = int(round(total / math.sqrt(n_inputs)))
                if mixed > INT32_MAX:
                    clipped += 1
                    mixed = INT32_MAX
                if mixed < INT32_MIN:
                    clipped += 1
                    mixed = INT32_MIN
                out.append(mixed)
        if clipped:
            warn(options.argv0, "sox", f"{options.combine}-combining clipped {clipped} samples; decrease volume?", options.verbosity)
        first = inputs[0]
        return AudioData(out, channels=max_channels, sample_rate=rate, encoding=first.encoding, bits=first.bits, precision=first.precision, reported_type=first.reported_type, handler_type=first.handler_type)
    raise SoXRuntimeError("sox", f"unsupported combine mode `{options.combine}'", 1)


def clone_audio(audio: AudioData) -> AudioData:
    return AudioData(
        samples=array("i", audio.samples),
        channels=audio.channels,
        sample_rate=audio.sample_rate,
        encoding=audio.encoding,
        bits=audio.bits,
        precision=audio.precision,
        reported_type=audio.reported_type,
        handler_type=audio.handler_type,
        comment=audio.comment,
    )


def apply_scalar_gain(audio: AudioData, factor: float, effect_name: Optional[str], argv0: str, verbosity: int) -> int:
    clipped = 0
    for index, value in enumerate(audio.samples):
        scaled = int(round(value * factor))
        if scaled > INT32_MAX:
            clipped += 1
            scaled = INT32_MAX
        elif scaled < INT32_MIN:
            clipped += 1
            scaled = INT32_MIN
        audio.samples[index] = scaled
    if clipped and effect_name:
        warn(argv0, effect_name, f"{effect_name} clipped {clipped} samples; decrease volume?", verbosity)
    return clipped


def effect_trim(audio: AudioData, args: list[str]) -> AudioData:
    if not args:
        return audio
    start = max(0, parse_time_spec(args[0], audio.sample_rate))
    length = None
    if len(args) > 1:
        length = max(0, parse_time_spec(args[1], audio.sample_rate))
    start = min(start, audio.frames)
    end = audio.frames if length is None else min(audio.frames, start + length)
    start_index = start * audio.channels
    end_index = end * audio.channels
    return AudioData(array("i", audio.samples[start_index:end_index]), channels=audio.channels, sample_rate=audio.sample_rate, encoding=audio.encoding, bits=audio.bits, precision=audio.precision, reported_type=audio.reported_type, handler_type=audio.handler_type, comment=audio.comment)


def effect_channels(audio: AudioData, args: list[str], options: GlobalOptions, emit_warning: bool = True) -> AudioData:
    if not args:
        return audio
    target = int(args[0])
    if target <= 0:
        raise SoXRuntimeError("sox", "channels effect requires a positive channel count")
    if target == audio.channels:
        return audio
    frames = audio.frames
    out = array("i")
    if audio.channels == 1 and target >= 2:
        for value in audio.samples:
            for _ in range(target):
                out.append(value)
    elif target == 1:
        for frame in range(frames):
            total = 0
            base = frame * audio.channels
            for channel in range(audio.channels):
                total += audio.samples[base + channel]
            out.append(average_round_up(total, audio.channels))
    elif target > audio.channels:
        for frame in range(frames):
            base = frame * audio.channels
            for channel in range(target):
                if channel < audio.channels:
                    out.append(audio.samples[base + channel])
                else:
                    out.append(audio.samples[base + audio.channels - 1])
    else:
        for frame in range(frames):
            base = frame * audio.channels
            for channel in range(target):
                source = int(round(channel * audio.channels / target))
                if source >= audio.channels:
                    source = audio.channels - 1
                out.append(audio.samples[base + source])
    return AudioData(out, channels=target, sample_rate=audio.sample_rate, encoding=audio.encoding, bits=audio.bits, precision=audio.precision, reported_type=audio.reported_type, handler_type=audio.handler_type, comment=audio.comment)


def effect_rate(audio: AudioData, args: list[str], options: GlobalOptions) -> AudioData:
    if not args:
        return audio
    target_rate = format_rate(args[-1])
    if target_rate <= 0 or target_rate == audio.sample_rate:
        return audio
    converted, _ = audioop.ratecv(le_bytes_from_ints(audio.samples), 4, audio.channels, audio.sample_rate, target_rate, None)
    out = ints_from_le_bytes(converted)
    clipped = sum(1 for value in out if value in (INT32_MIN, INT32_MAX))
    if clipped:
        warn(options.argv0, "rate", f"rate clipped {clipped} samples; decrease volume?", options.verbosity)
    return AudioData(out, channels=audio.channels, sample_rate=target_rate, encoding=audio.encoding, bits=audio.bits, precision=audio.precision, reported_type=audio.reported_type, handler_type=audio.handler_type, comment=audio.comment)


def parse_freq_expr(text: str) -> tuple[float, float]:
    def single(part: str) -> float:
        part = part.strip()
        if part.startswith("%"):
            return 440.0 * (2.0 ** (float(part[1:]) / 12.0))
        if part.endswith("k"):
            return float(part[:-1]) * 1000.0
        return float(part)

    body = text
    if body.startswith("+"):
        body = body[1:]
    if "-" in body and not body.startswith("-"):
        left, right = body.split("-", 1)
        return single(left), single(right)
    return single(body), single(body)


def synth_waveform(name: str, phase: float, rng: random.Random, state: dict[str, float]) -> float:
    lowered = name.lower()
    if lowered in ("sine", "sin"):
        return math.sin(phase)
    if lowered in ("square", "squ"):
        return 1.0 if math.sin(phase) >= 0 else -1.0
    if lowered in ("triangle", "tri"):
        return (2.0 / math.pi) * math.asin(math.sin(phase))
    if lowered in ("sawtooth", "saw"):
        return 2.0 * ((phase / (2.0 * math.pi)) % 1.0) - 1.0
    if lowered in ("trapezium", "trap"):
        tri = (2.0 / math.pi) * math.asin(math.sin(phase))
        return max(-1.0, min(1.0, tri * 1.5))
    if lowered in ("noise", "whitenoise"):
        return rng.uniform(-1.0, 1.0)
    if lowered == "brownnoise":
        previous = state.get("brown", 0.0)
        previous += rng.uniform(-0.1, 0.1)
        previous = max(-1.0, min(1.0, previous))
        state["brown"] = previous
        return previous
    if lowered == "pinknoise":
        previous = state.get("pink", 0.0)
        previous = 0.98 * previous + 0.02 * rng.uniform(-1.0, 1.0)
        state["pink"] = previous
        return max(-1.0, min(1.0, previous * 4))
    if lowered == "pluck":
        return math.sin(phase) * max(0.0, state.get("envelope", 1.0))
    return math.sin(phase)


def effect_synth(audio: AudioData, args: list[str], options: GlobalOptions) -> AudioData:
    tokens = list(args)
    while tokens and tokens[0].startswith("-"):
        if tokens[0] in ("-n",):
            tokens.pop(0)
            continue
        if tokens[0] == "-j" and len(tokens) > 1:
            tokens = tokens[2:]
            continue
        break
    length_seconds = audio.duration if audio.frames else 0.0
    if tokens and not is_waveform_token(tokens[0]):
        length_seconds = float(tokens.pop(0))
    if length_seconds <= 0:
        length_seconds = 0.0
    sample_rate = audio.sample_rate or 48000
    channels = audio.channels or 1
    frames = int(round(length_seconds * sample_rate))
    rng = random.Random(0 if options.deterministic else None)
    oscillators: list[tuple[str, float, float]] = []
    while tokens:
        waveform = tokens.pop(0)
        if not tokens:
            break
        freq1, freq2 = parse_freq_expr(tokens.pop(0))
        oscillators.append((waveform, freq1, freq2))
    if not oscillators:
        oscillators.append(("sine", 440.0, 440.0))
    out = array("i")
    for frame in range(frames):
        t = frame / sample_rate if sample_rate else 0.0
        sample = 0.0
        for waveform, freq_start, freq_end in oscillators:
            freq = freq_start if frames <= 1 else freq_start + (freq_end - freq_start) * (frame / (frames - 1))
            phase = 2.0 * math.pi * freq * t
            state = {"envelope": math.exp(-3.0 * t / max(length_seconds, 1e-9))}
            sample += synth_waveform(waveform, phase, rng, state)
        sample = max(-1.0, min(1.0, sample))
        value = float_to_int32(sample)
        for _ in range(channels):
            out.append(value)
    return AudioData(out, channels=channels, sample_rate=sample_rate, encoding="signed-integer", bits=32, precision=32, reported_type="wav", handler_type="wav")


def is_waveform_token(token: str) -> bool:
    return token.lower() in {
        "sine",
        "sin",
        "square",
        "squ",
        "triangle",
        "tri",
        "saw",
        "sawtooth",
        "trapezium",
        "trap",
        "noise",
        "whitenoise",
        "pinknoise",
        "brownnoise",
        "pluck",
    }


def effect_reverse(audio: AudioData) -> AudioData:
    out = array("i")
    for frame in range(audio.frames - 1, -1, -1):
        base = frame * audio.channels
        out.extend(audio.samples[base : base + audio.channels])
    return AudioData(out, channels=audio.channels, sample_rate=audio.sample_rate, encoding=audio.encoding, bits=audio.bits, precision=audio.precision, reported_type=audio.reported_type, handler_type=audio.handler_type, comment=audio.comment)


def effect_norm(audio: AudioData) -> AudioData:
    peak = max((abs(value) for value in audio.samples), default=0)
    if peak == 0:
        return audio
    factor = INT32_MAX / float(peak)
    apply_scalar_gain(audio, factor, effect_name=None, argv0="", verbosity=0)
    return audio


def analyze_stat(audio: AudioData) -> str:
    samples = list(audio.samples)
    count = len(samples)
    if count == 0:
        volume_adjustment = 0.0
        lines = [
            "Samples read:                 0",
            "Length (seconds):      0.000000",
            f"Scaled by:         {float(INT32_MAX):.1f}",
            "Maximum amplitude:     0.000000",
            "Minimum amplitude:     0.000000",
            "Midline amplitude:     0.000000",
            "Mean    norm:          0.000000",
            "Mean    amplitude:     0.000000",
            "RMS     amplitude:     0.000000",
            "Maximum delta:         0.000000",
            "Minimum delta:         0.000000",
            "Mean    delta:         0.000000",
            "RMS     delta:         0.000000",
            "Rough   frequency:            0",
            f"Volume adjustment:        {volume_adjustment:.3f}",
            "",
            "Try: -t raw -e mu-law -b 8 ",
        ]
        return "\n".join(lines) + "\n"
    normalized = [normalize_sample(value) for value in samples]
    maximum = max(normalized)
    minimum = min(normalized)
    mean_norm = sum(abs(value) for value in normalized) / count
    mean_amp = sum(normalized) / count
    rms = math.sqrt(sum(value * value for value in normalized) / count)
    deltas = [abs(normalized[index] - normalized[index - 1]) for index in range(1, count)]
    max_delta = max(deltas, default=0.0)
    min_delta = min(deltas, default=0.0)
    mean_delta = sum(deltas) / len(deltas) if deltas else 0.0
    rms_delta = math.sqrt(sum(delta * delta for delta in deltas) / len(deltas)) if deltas else 0.0
    rough_frequency = 0
    if audio.duration > 0:
        crossings = 0
        previous = normalized[0]
        for current in normalized[1:]:
            if (previous <= 0 < current) or (previous >= 0 > current):
                crossings += 1
            previous = current
        rough_frequency = int((crossings / 2.0) / audio.duration)
    volume_adjustment = 0.0 if max(abs(maximum), abs(minimum)) == 0 else 1.0 / max(abs(maximum), abs(minimum))
    lines = [
        f"Samples read:{count:18d}",
        f"Length (seconds):{audio.duration:14.6f}",
        f"Scaled by:{float(INT32_MAX):21.1f}",
        f"Maximum amplitude:{maximum:13.6f}",
        f"Minimum amplitude:{minimum:13.6f}",
        f"Midline amplitude:{((maximum + minimum) / 2.0):13.6f}",
        f"Mean    norm:{mean_norm:19.6f}",
        f"Mean    amplitude:{mean_amp:13.6f}",
        f"RMS     amplitude:{rms:13.6f}",
        f"Maximum delta:{max_delta:18.6f}",
        f"Minimum delta:{min_delta:18.6f}",
        f"Mean    delta:{mean_delta:19.6f}",
        f"RMS     delta:{rms_delta:18.6f}",
        f"Rough   frequency:{rough_frequency:13d}",
        f"Volume adjustment:{volume_adjustment:13.3f}",
        "",
        "Try: -t raw -e mu-law -b 8 ",
    ]
    return "\n".join(lines) + "\n"


def analyze_stat_v(audio: AudioData) -> str:
    peak = max((abs(normalize_sample(value)) for value in audio.samples), default=0.0)
    if peak == 0:
        return "0.000\n"
    return f"{1.0 / peak:.3f}\n"


def db_or_inf(value: float) -> str:
    if value <= 0:
        return "     -inf"
    return f"{20.0 * math.log10(value):10.2f}"


def analyze_stats(audio: AudioData) -> str:
    samples = [normalize_sample(value) for value in audio.samples]
    if not samples:
        samples = [0.0]
    dc = sum(samples) / len(samples)
    min_level = min(samples)
    max_level = max(samples)
    peak = max(abs(min_level), abs(max_level))
    rms = math.sqrt(sum(value * value for value in samples) / len(samples))
    peak_count = sum(1 for value in samples if abs(value) >= peak * 0.99999) if peak else 0
    crest = 0.0 if rms == 0 else peak / rms
    lines = [
        f"DC offset {dc:10.6f}",
        f"Min level {min_level:10.6f}",
        f"Max level {max_level:10.6f}",
        f"Pk lev dB {db_or_inf(peak)}",
        f"RMS lev dB {db_or_inf(rms)}",
        f"RMS Pk dB {db_or_inf(rms)}",
        f"RMS Tr dB {db_or_inf(max(rms * 0.99, 0.0))}",
        f"Crest factor {crest:7.2f}",
        f"Flat factor {0.0:7.2f}",
        f"Pk count {peak_count:11d}",
        f"Bit-depth {audio.precision:7d}/{audio.bits:<2d}",
        f"Num samples {format_stats_count(len(audio.samples)):>8}",
        f"Length s {audio.duration:11.3f}",
        f"Scale max {peak:10.6f}",
        f"Window s {0.050:11.3f}",
    ]
    return "\n".join(lines) + "\n"


def apply_effects(audio: AudioData, effects: list[tuple[str, list[str]]], options: GlobalOptions) -> AudioData:
    current = audio
    for name, args in effects:
        if name == "trim":
            current = effect_trim(current, args)
        elif name == "channels":
            current = effect_channels(current, args, options)
        elif name == "rate":
            current = effect_rate(current, args, options)
        elif name == "vol":
            gain = float(args[0]) if args else 1.0
            kind = args[1].lower() if len(args) > 1 else "amplitude"
            if kind == "db":
                factor = 10.0 ** (gain / 20.0)
            elif kind == "power":
                factor = math.sqrt(gain)
            else:
                factor = gain
            apply_scalar_gain(current, factor, "vol", options.argv0, options.verbosity)
        elif name == "gain":
            factor = 1.0
            normalize = False
            for token in args:
                if token == "-n":
                    normalize = True
                elif re.fullmatch(r"[+-]?\d+(?:\.\d+)?", token):
                    factor *= 10.0 ** (float(token) / 20.0)
            if normalize:
                current = effect_norm(current)
            apply_scalar_gain(current, factor, "gain", options.argv0, options.verbosity)
        elif name == "synth":
            current = effect_synth(current, args, options)
        elif name == "reverse":
            current = effect_reverse(current)
        elif name == "norm":
            current = effect_norm(current)
        elif name == "stat":
            if "-v" in args:
                emit_stderr(analyze_stat_v(current))
            else:
                emit_stderr(analyze_stat(current))
        elif name == "stats":
            emit_stderr(analyze_stats(current))
        else:
            raise SoXRuntimeError("sox", f"unsupported effect `{name}'", 1)
    return current


def sox_usage(argv0: str, play_mode: bool) -> str:
    fixture = "play_help.txt" if play_mode else "sox_help.txt"
    return replace_program_banner(fixture_text(fixture), argv0)


def print_help_effect(argv0: str, name: str) -> int:
