def print_invalid_option(argv0: str, token: str) -> int:
    emit_stderr(f"{argv0} WARN getopt: parameter not recognized from `{token}'\n")
    fail(argv0, "sox", "invalid option", DEFAULT_VERBOSITY)
    sys.stdout.write("\n" + sox_usage(argv0, play_mode=False))
    return 1


def parse_verbosity(token: str, current: int) -> int:
    if token == "-V":
        return current + 1
    if token.startswith("-V"):
        return int(token[2:] or current + 1)
    return current


def parse_info_mode(argv0: str, args: list[str]) -> int:
    verbosity = DEFAULT_VERBOSITY
    selector: Optional[str] = None
    total = False
    had_option = False
    files: list[str] = []
    index = 0
    while index < len(args):
        token = args[index]
        if files:
            files.append(token)
            index += 1
            continue
        if token == "--":
            files.extend(args[index + 1 :])
            break
        if token.startswith("--"):
            opt = "-"
            emit_stderr(f"{argv0} WARN getopt: option `-' not recognized\n")
