    if total and selector not in (None, "s", "d", "D"):
        emit_stderr("soxi: ignoring -T; n/a with other given option")
    if not files:
        if not had_option:
            sys.stdout.write(replace_program_banner(fixture_text("soxi_usage.txt"), argv0))
        return 0
    successes: list[AudioData] = []
    display_paths: list[str] = []
    exit_code = 0
    outputs: list[str] = []
    for path in files:
        try:
            audio = open_info_audio(argv0, path, verbosity)
        except SoXRuntimeError as exc:
            fail(argv0, exc.category, exc.message, verbosity)
            exit_code = 1
            continue
        successes.append(audio)
        display_paths.append(path)
