            outputs.append(audio.reported_type + "\n")
        elif selector == "r":
            outputs.append(f"{audio.sample_rate}\n")
        elif selector == "c":
            outputs.append(f"{audio.channels}\n")
        elif selector == "s":
            outputs.append(f"{audio.frames}\n")
        elif selector == "d":
            outputs.append(format_duration_clock(audio.duration) + "\n")
        elif selector == "D":
            outputs.append(format_seconds_six(audio.duration) + "\n")
        elif selector == "b":
            outputs.append(f"{audio.bits}\n")
        elif selector == "B":
            bitrate = 0 if audio.duration == 0 else (estimate_file_size(audio, audio.handler_type, path) * 8.0 / audio.duration)
            outputs.append((format_si(bitrate) if bitrate else "0") + "\n")
        elif selector == "p":
            outputs.append(f"{audio.precision}\n")
        elif selector == "e":
            outputs.append(format_short_encoding(audio.encoding) + "\n")
        elif selector == "a":
            if audio.comment:
                outputs.append(audio.comment + "\n")
        else:
            outputs.append(render_full_info(path, audio))
    if total and selector in ("s", "d", "D"):
        total_value = sum(audio.frames if selector == "s" else audio.duration for audio in successes)
        if selector == "s":
            sys.stdout.write(f"{total_value:.6f}\n")
        elif selector == "d":
            sys.stdout.write(format_duration_clock(total_value) + "\n")
        else:
            sys.stdout.write(format_seconds_six(total_value) + "\n")
        return exit_code
    sys.stdout.write("".join(outputs))
    if total and selector is None and len(successes) >= 2:
        total_duration = sum(audio.duration for audio in successes)
        sys.stdout.write(f"Total Duration of {len(successes)} files: {format_duration_clock(total_duration)}\n")
    return exit_code


def open_info_audio(argv0: str, path: str, verbosity: int) -> AudioData:
    spec = FileSpec(path=path, options=FileOptions())
    try:
        return open_audio_for_read(argv0, spec, verbosity)
    except SoXRuntimeError as exc:
        suffix = Path(path).suffix.lower().lstrip(".")
        if suffix in RAW_TYPE_ALIASES and suffix != "raw":
            details = raw_type_details(suffix)
            options = FileOptions(file_type=suffix, encoding=details.get("encoding"), bits=details.get("bits"))
            return open_audio_for_read(argv0, FileSpec(path=path, options=options), verbosity)
        raise exc


def estimate_file_size(audio: AudioData, handler_type: str, path: str) -> int:
    if path != "-" and Path(path).exists():
        try:
            return Path(path).stat().st_size
        except OSError:
            pass
    if handler_type == "wav":
        return len(write_wav(audio, audio.encoding, audio.bits))
    if handler_type == "sox":
        return len(write_sox_native(audio, audio.comment))
    payload, _ = encode_samples(audio.samples, audio.encoding, audio.bits)
    return len(payload)


def render_full_info(path: str, audio: AudioData) -> str:
    suffix = Path(path).suffix.lower().lstrip(".")
    type_suffix = f" ({audio.reported_type})" if suffix != audio.reported_type else ""
    lines = [f"\nInput File     : '{path}'{type_suffix}"]
    lines.append(f"Channels       : {audio.channels}")
    lines.append(f"Sample Rate    : {audio.sample_rate}")
    lines.append(f"Precision      : {audio.precision}-bit")
    if audio.frames > 0:
        sectors = audio.duration * 75.0
        lines.append(f"Duration       : {format_duration_clock(audio.duration)} = {audio.frames} samples ~ {sectors:g} CDDA sectors")
        file_size = estimate_file_size(audio, audio.handler_type, path)
        lines.append(f"File Size      : {format_si(file_size)}")
        bitrate = file_size * 8.0 / audio.duration
        lines.append(f"Bit Rate       : {format_si(bitrate)}")
    lines.append(f"Sample Encoding: {format_encoding_description(audio.encoding, audio.bits)}")
    if audio.comment:
        if "\n" in audio.comment:
            lines.append("Comments       : ")
            lines.extend(audio.comment.splitlines())
        else:
            lines.append(f"Comment        : '{audio.comment}'")
    return "\n".join(lines) + "\n\n"


def parse_file_options(argv0: str, args: list[str], mode: str) -> tuple[GlobalOptions, list[FileSpec], list[tuple[str, list[str]]], Optional[int]]:
    options = GlobalOptions(argv0=argv0)
    pending = FileOptions()
    files: list[FileSpec] = []
    index = 0
    min_files_before_effect = 2 if mode == "sox" else 1
    while index < len(args):
        token = args[index]
        if token in ("-h", "--help"):
            sys.stdout.write(sox_usage(argv0, play_mode=(mode == "play")))
            return options, files, [], 0
        if token == "--version":
            sys.stdout.write(version_text(argv0))
            return options, files, [], 0
        if token == "--help-effect":
            name = args[index + 1] if index + 1 < len(args) else ""
            return options, files, [], print_help_effect(argv0, name)
        if token == "--help-format":
            name = args[index + 1] if index + 1 < len(args) else ""
            return options, files, [], print_help_format(argv0, name)
        if token in ("--i", "--info"):
            if files:
                return options, files, [], print_invalid_option(argv0, token)
            return options, files, [], parse_info_mode(argv0, args[index + 1 :])
        if token in ("-V",) or token.startswith("-V"):
            options.verbosity = parse_verbosity(token, options.verbosity)
            index += 1
            continue
        if token in ("-D", "--no-dither"):
            options.no_dither = True
            index += 1
            continue
        if token == "-R":
            options.deterministic = True
            index += 1
            continue
        if token in ("-m", "--combine"):
            if token == "-m":
                options.combine = "mix"
                index += 1
                continue
            if index + 1 >= len(args):
                raise SoXRuntimeError("sox", "missing argument to --combine", 1)
            options.combine = args[index + 1]
            index += 2
            continue
        if token == "-M":
            options.combine = "merge"
            index += 1
            continue
        if token == "-T":
            options.combine = "multiply"
            index += 1
            continue
        if token in ("-q", "-S", "--show-progress", "--no-show-progress", "--clobber", "--no-clobber", "--single-threaded", "--multi-threaded", "-G", "--guard"):
            index += 1
            continue
        if token in ("-t", "--type", "-e", "--encoding", "-b", "--bits", "-c", "--channels", "-r", "--rate", "-v", "--volume", "--comment", "--add-comment", "--comment-file"):
            if index + 1 >= len(args):
                raise SoXRuntimeError("sox", f"missing argument to {token}", 1)
            value = args[index + 1]
            if token in ("-t", "--type"):
                pending.file_type = value
            elif token in ("-e", "--encoding"):
                pending.encoding = value.lower()
            elif token in ("-b", "--bits"):
                pending.bits = int(value)
            elif token in ("-c", "--channels"):
                pending.channels = int(value)
            elif token in ("-r", "--rate"):
                pending.rate = format_rate(value)
            elif token in ("-v", "--volume"):
                pending.volume = float(value)
            elif token in ("--comment", "--add-comment"):
                pending.comment = value
            elif token == "--comment-file":
                pending.comment = Path(value).read_text(encoding="utf-8")
            index += 2
            continue
        if len(files) >= min_files_before_effect and token.rstrip("+#*") in KNOWN_EFFECTS:
            break
        if token.startswith("-") and token not in SPECIAL_FILENAMES:
            return options, files, [], print_invalid_option(argv0, token)
        files.append(FileSpec(path=token, options=pending))
        pending = FileOptions()
        index += 1
    effects = parse_effects(args[index:])
    return options, files, effects, None


def parse_effects(tokens: list[str]) -> list[tuple[str, list[str]]]:
    effects: list[tuple[str, list[str]]] = []
    index = 0
    while index < len(tokens):
        name = tokens[index].rstrip("+#*")
        if name not in KNOWN_EFFECTS:
            raise SoXRuntimeError("sox", f"unsupported effect `{name}'", 1)
        index += 1
        args: list[str] = []
        while index < len(tokens):
            candidate = tokens[index].rstrip("+#*")
            if candidate in KNOWN_EFFECTS:
                break
            args.append(tokens[index])
            index += 1
        effects.append((name, args))
    return effects


def run_sox(argv0: str, args: list[str], mode: str) -> int:
    if mode == "rec":
        fail(argv0, "sox", "Sorry, there is no default audio device configured", DEFAULT_VERBOSITY)
        return 1
    options, files, effects, early = parse_file_options(argv0, args, mode)
    if early is not None:
        return early
    if mode == "play":
        if not files:
            fail(argv0, "sox", "Sorry, there is no default audio device configured", options.verbosity)
            return 1
        fail(argv0, "sox", "Sorry, there is no default audio device configured", options.verbosity)
        return 1
    if len(files) < 2:
        fail(argv0, "sox", "No input filenames specified", options.verbosity)
        sys.stdout.write("\n" + sox_usage(argv0, play_mode=False))
        return 1
    input_specs = files[:-1]
    output_spec = files[-1]
    try:
        inputs = [open_audio_for_read(argv0, spec, options.verbosity) for spec in input_specs]
        current = combine_inputs(inputs, options)
        current = apply_effects(current, effects, options)
        write_audio(argv0, current, output_spec, inputs[0] if inputs else None, options)
    except SoXRuntimeError as exc:
        fail(argv0, exc.category, exc.message, options.verbosity)
        return exc.exit_code
    return 0


def main(argv: Optional[list[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    argv0 = sys.argv[0] if argv is None else "sox"
    name = Path(argv0).name
    if name == "soxi":
        return parse_info_mode(argv0, args)
    if name == "play":
        return run_sox(argv0, args, "play")
    if name == "rec":
        return run_sox(argv0, args, "rec")
    return run_sox(argv0, args, "sox")


if __name__ == "__main__":
    raise SystemExit(main())

